{"source": "def investigate(context, acquire):
    values = context["values"]
    n = len(values)
    if n == 0:
        return 0
    best = None
    best_err = None
    for a in (-2, -1, 0, 1, 2):
        for b in (-2, -1, 0, 1, 2):
            for c in (-2, -1, 0, 1, 2):
                for g in (-2, -1, 1, 2):
                    for mode in (0, 1):
                        for passes in (1, 2, 3, 4):
                            contrib = []
                            for i in range(n):
                                x = values[i]
                                p = a * x + b * x * x + c * x * x * x
                                if mode == 0:
                                    prev = values[i - 1] if i > 0 else 0
                                else:
                                    prev = sum(values[:i])
                                contrib.append(p + g * x * prev)
                            arr = contrib
                            for _ in range(passes):
                                acc = 0
                                nxt = []
                                for v in arr:
                                    acc = acc + v
                                    nxt.append(acc)
                                arr = nxt
                            val = arr[-1]
                            err = 0
                            for i in range(n):
                                err = err + abs(contrib[i])
                            if best is None or err < best_err:
                                best_err = err
                                best = val
    return best
